function updateLocations(){const city=$('#cityFilter').value,purpose=$('#purposeFilter').value;const cities=city==='All cities'?['Nicosia','Limassol','Larnaca','Paphos','Paralimni']:[city];$('#locationResults').innerHTML=cities.map(c=>`<article class="location-item"><h3>${c} · ${purpose.toLowerCase()}</h3><p>Select this location when sending your ${purpose==='Showroom'?'test-drive':'service'} request.</p>${act(purpose==='Showroom'?'Request a test drive':'Request a service appointment',purpose==='Showroom'?'test':'service')}</article>`).join('');}
const dialog=$('#requestDialog');function openRequest(type){if(type==='test'){closeMenus(true);window.startUniTestDrive(current);return;}const requestOrigin=document.activeElement;const fromMobile=!$('#mobileMenu').hidden&&$('#mobileMenu').contains(requestOrigin);closeMenus(true);lastFocus=fromMobile?$('.menu-toggle'):requestOrigin;const titles={test:'Request a test drive.',quote:'Request a quote.',service:'Request a service appointment.',parts:'Ask about a part.',warranty:'Ask about your warranty.',newsletter:'Subscribe to updates.',feedback:'Tell us about your experience.',general:'How can we help?'};$('#dialogTitle').textContent=titles[type]||titles.general;$('#dialogDescription').textContent=(current.startsWith('model-')?'Your selected model: '+(sampleModels.find(([,r])=>'model-'+r===current)?.[0]||'Vehicle')+'. ':'')+(current==='vehicle'||current==='vehicle-skoda'?'Your selected car: '+(current==='vehicle'?'CUPRA':'Škoda')+'. ':'')+(type==='service'?'Choose a preferred location. The live team would contact you to confirm the appointment.':'Tell the team how to reach you. The live form would keep the context of this page.');let modelField=$('#requestModelField');if(!modelField){$('#choiceLabel').insertAdjacentHTML('beforebegin','<label id="requestModelField">Vehicle model<select id="requestModel" aria-label="Vehicle model"><option value="">Choose a model</option></select></label>');modelField=$('#requestModelField')}modelField.hidden=!['test','quote'].includes(type);$('#requestModel').innerHTML='<option value="">Choose a sample model</option>'+sampleModels.map(([n,r])=>`<option value="${r}" ${current==='model-'+r?'selected':''}>${n}</option>`).join('')+'<option value="help">I need help choosing</option>';$('#requestModel').required=['test','quote'].includes(type);$('#choiceLabel').hidden=['newsletter','feedback'].includes(type);$('.form-fields').hidden=false;$('.form-success').hidden=true;$('#requestForm button[type=submit]').hidden=false;document.body.classList.add('dialog-open');dialog.showModal();}
document.addEventListener('click',e=>{const localLink=e.target.closest('a[href^="#"]');if(localLink&&!localLink.hasAttribute('data-scroll')){const fromMobile=$('#mobileMenu').contains(localLink);closeMenus();if(fromMobile)requestAnimationFrame(()=>$('#main').focus({preventScroll:true}));}if(e.target.closest('.mega-close')){const opener=document.querySelector('[data-menu="'+activeMenu+'"]');closeMenus();opener?.focus();return;}const menu=e.target.closest('[data-menu]');if(menu){setMenu(menu.dataset.menu);return;}const action=e.target.closest('[data-action]');if(action){openRequest(action.dataset.action);return;}const go=e.target.closest('[data-go]');if(go){if(location.hash==='#'+go.dataset.go)render(go.dataset.go);else location.hash=go.dataset.go;return;}const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();$('#'+scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}const comp=e.target.closest('[data-compare]');if(comp){const old=comp.dataset.compare==='old';$('.legacy-rail').hidden=!old;document.querySelectorAll('[data-compare]').forEach(b=>{b.classList.toggle('active',b===comp);b.setAttribute('aria-pressed',String(b===comp));});return;}const resource=e.target.closest('[data-resource]');if(resource){openRequest('general');$('#dialogTitle').textContent=resource.dataset.resource;$('#dialogDescription').textContent='This prototype shows where this resource will be available. The production document or policy is not connected.';$('.form-fields').hidden=true;$('#requestForm button[type=submit]').hidden=true;}});
$('.menu-toggle').addEventListener('click',()=>{const open=$('.menu-toggle').getAttribute('aria-expanded')!=='true';if(!open){closeMenus();return;}closeMenus(true);if(open){renderMobileMenu();$('#mobileMenu').hidden=false;$('#mobileMenu').inert=false;sizeMobileMenu();requestAnimationFrame(()=>$('#mobileMenu .mobile-view-title')?.focus({preventScroll:true}));$('#scrim').hidden=false;$('.menu-toggle').setAttribute('aria-expanded','true');document.body.classList.add('menu-open');document.querySelectorAll('#main,body>footer').forEach(el=>el.inert=true);$('.menu-toggle').setAttribute('aria-label','Close navigation');$('.menu-toggle svg use').setAttribute('href','#close');}});$('#scrim').addEventListener('click',closeMenus);document.addEventListener('keydown',e=>{if(e.key==='Escape'){const opener=activeMenu?document.querySelector('[data-menu="'+activeMenu+'"]'):$('.menu-toggle');closeMenus();if(!dialog.open)opener?.focus();}});$('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.classList.remove('dialog-open');lastFocus?.focus();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});$('#requestForm').addEventListener('submit',e=>{e.preventDefault();$('.form-success').hidden=false;$('#requestForm button[type=submit]').hidden=true;});document.addEventListener('change',e=>{if(e.target.matches('#cityFilter,#purposeFilter'))updateLocations();});window.addEventListener('hashchange',()=>render(location.hash.slice(1)||'home'));render(location.hash.slice(1)||'home');

